// Native FAR EKF calls with passive snapshots. Synthetic states only, not C1 replay.
#include <iostream>
#include <nlohmann/json.hpp>
#include "tam_state_estimation/kalman_filter/ekf.hpp"
using C=tam::core::state::EKF_3D;using F=tam::core::state::EKF<C>;using J=nlohmann::json;
template<class M> J mat(const M& m){J a=J::array();for(int i=0;i<m.rows();++i){J b=J::array();for(int j=0;j<m.cols();++j)b.push_back(m(i,j));a.push_back(b);}return a;}
F setup(){F f;f.x_.setZero();f.P_.setIdentity();f.P_*=.1;f.Q_.setZero();f.R_.setIdentity();f.outlier_bound_.setConstant(100.);Eigen::Vector<double,C::MEASUREMENT_VECTOR_SIZE> mask;mask.setZero();for(int i=0;i<3;++i){mask(i)=1.;mask(C::MEASUREMENT_VECTOR_OFFSET_ORIENTATION+i)=1.;f.R_(i,i)=i==2?.07:.05;f.R_(C::MEASUREMENT_VECTOR_OFFSET_ORIENTATION+i,C::MEASUREMENT_VECTOR_OFFSET_ORIENTATION+i)=i==2?.0002:.3;}f.update_measurement_matrix(mask);return f;}
J correct(F& f,const Eigen::Vector<double,C::MEASUREMENT_VECTOR_SIZE>& z,bool trace){auto before=f.x_;auto P=f.P_pred_;auto H=f.H_;auto R=f.R_;f.update(z);if(!trace)return J();auto S=H*P*H.transpose()+R;return J{{"pre",mat(before)},{"pred",mat(f.x_pred_)},{"Ppred",mat(P)},{"H",mat(H)},{"R",mat(R)},{"S",mat(S)},{"K",mat(f.K_)},{"raw_residual",mat(f.residuals_raw_)},{"clipped_residual",mat(f.residuals_)},{"post",mat(f.x_)},{"Ppost",mat(f.P_)}};}
int main(){Eigen::Vector<double,C::INPUT_VECTOR_SIZE> u;u.setZero();u(5)=9.81;auto a=setup(),b=a;Eigen::Vector<double,C::MEASUREMENT_VECTOR_SIZE> z;z.setZero();z(1)=.3;J traces=J::array();double parity=0;for(int t=0;t<5;++t){a.predict(u);b.predict(u);correct(a,z,false);traces.push_back(correct(b,z,true));parity=std::max(parity,(a.x_-b.x_).cwiseAbs().maxCoeff());parity=std::max(parity,(a.P_-b.P_).cwiseAbs().maxCoeff());}auto once=setup();double first_y=0.;for(int t=0;t<5;++t){if(t>0){Eigen::Vector<double,C::MEASUREMENT_VECTOR_SIZE> off;off.setZero();once.update_measurement_matrix(off);}once.predict(u);correct(once,z,false);if(t==0)first_y=once.x_(1);}J pred=J::array();for(int n:{1,5,10}){auto f=setup();f.x_(3)=.03;f.x_(4)=-.02;f.x_(5)=.5;f.x_(6)=35.;f.x_(7)=1.2;u.setZero();u(2)=.2;u(4)=7.;u(5)=9.81;for(int i=0;i<n;++i){f.predict(u);f.x_=f.x_pred_;f.P_=f.P_pred_;}pred.push_back(J{{"steps",n},{"x",mat(f.x_)},{"P",mat(f.P_)}});}std::cout<<J{{"scope","synthetic native9D controlled functions; no real C1 prior substitution"},{"trace_equivalence_max_abs",parity},{"same_id_repeated5",traces},{"single_update_position_y",once.x_(1)},{"first_update_y",first_y},{"comparison_horizon_ms",50},{"repeat5_position_y",a.x_(1)},{"single_Pyy",once.P_(1,1)},{"repeat5_Pyy",a.P_(1,1)},{"prediction",pred}}.dump()<<std::endl;return parity>1e-12;}
